INSERT INTO collection_pages VALUES('d785484049ca07f3a70d654929b8192789dee9c8e2c12975fa416ddd7f8727a8','2a62d4eb346ef404a9424652289fbbd916dcd5e62f65005ecb4d0f4c8047021b','{"hasNext":false,"items":[{"author":{"account":null,"email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"authoredDate":"2026-09-11T20:34:54Z","committedDate":"2026-09-11T20:34:54Z","committer":{"account":null,"email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"observedAt":"2026-10-08T18:00:16.708Z","repositoryId":541637329,"sha":"de844aa75cf9771ef577f10a79a72fba481bc465"},{"author":{"account":null,"email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"authoredDate":"2026-09-11T20:23:50Z","committedDate":"2026-09-11T20:23:50Z","committer":{"account":null,"email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"observedAt":"2026-10-08T18:00:16.708Z","repositoryId":541637329,"sha":"ddb95cb3564910aaf742e0ea8088d23a806d98a5"},{"author":{"account":null,"email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"authoredDate":"2026-09-11T20:09:08Z","committedDate":"2026-09-11T20:09:08Z","committer":{"account":null,"email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"observedAt":"2026-10-08T18:00:16.708Z","repositoryId":541637329,"sha":"974e1016afd7b3070d16be73136f28d0d3171b16"},{"author":{"account":null,"email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"authoredDate":"2026-09-11T19:28:32Z","committedDate":"2026-09-11T19:28:32Z","committer":{"account":null,"email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"observedAt":"2026-10-08T18:00:16.708Z","repositoryId":541637329,"sha":"992ec36d141124c88d5f2d825529fdd159da2efb"},{"author":{"account":null,"email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"authoredDate":"2026-09-11T18:22:17Z","committedDate":"2026-09-11T18:22:17Z","committer":{"account":null,"email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"observedAt":"2026-10-08T18:00:16.708Z","repositoryId":541637329,"sha":"cb57dbe7518c23b9bcd99d5317fee94f1f30ff2d"},{"author":{"account":null,"email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"authoredDate":"2026-09-11T18:08:21Z","committedDate":"2026-09-11T18:08:21Z","committer":{"account":null,"email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"observedAt":"2026-10-08T18:00:16.708Z","repositoryId":541637329,"sha":"d2174a08efadac1046a944e9935f49b8743872ee"},{"author":{"account":null,"email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"authoredDate":"2026-09-11T18:07:54Z","committedDate":"2026-09-11T18:07:54Z","committer":{"account":null,"email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"observedAt":"2026-10-08T18:00:16.708Z","repositoryId":541637329,"sha":"575a906becdd9a1d66d962168794bb84e3a76795"},{"author":{"account":null,"email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"authoredDate":"2026-09-11T17:59:34Z","committedDate":"2026-09-11T17:59:47Z","committer":{"account":null,"email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"observedAt":"2026-10-08T18:00:16.708Z","repositoryId":541637329,"sha":"4fd2df2009bbb563be30d3410c280bb75c78fd89"},{"author":{"account":null,"email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"authoredDate":"2026-09-11T14:19:16Z","committedDate":"2026-09-11T14:19:16Z","committer":{"account":null,"email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"observedAt":"2026-10-08T18:00:16.708Z","repositoryId":541637329,"sha":"bc982b350e1d692037febe5a8ca5590d7c5d0861"}],"observedAt":"2026-10-08T18:00:16.708Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/de844aa75cf9771ef577f10a79a72fba481bc465/comments","commit":{"author":{"date":"2026-09-11T20:34:54Z","email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"comment_count":0,"committer":{"date":"2026-09-11T20:34:54Z","email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"message":"Declare ArchiveComponent so the project archive renders\n\nThe archive was routed but the component was declared in no NgModule — the\nline sat commented out in AppModule — so /projects had always rendered an\nempty page. That only became visible once the work section started linking to\nit. It now has its own module carrying CommonModule and the translate loader,\nand renders all ten rows in both locales.\n\nSeparators in the technology column came out one position off in Arabic:\nisolating each name to stop bidi reversing \"AG Grid\" pins the separator to the\nspan''s LTR end, which places it between the wrong pair. Spacing carries the\nsame meaning without the reordering.\n\nCo-Authored-By: Claude Opus 5 (1M context) <noreply@anthropic.com>","tree":{"sha":"4f4ac81271933e4097a57d2e24ecb260eba04d1c","url":"https://api.github.com/repos/mobasherahmed/Portfolio/git/trees/4f4ac81271933e4097a57d2e24ecb260eba04d1c"},"url":"https://api.github.com/repos/mobasherahmed/Portfolio/git/commits/de844aa75cf9771ef577f10a79a72fba481bc465","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/mobasherahmed/Portfolio/commit/de844aa75cf9771ef577f10a79a72fba481bc465","node_id":"C_kwDOIEi60doAKGRlODQ0YWE3NWNmOTc3MWVmNTc3ZjEwYTc5YTcyZmJhNDgxYmM0NjU","parents":[{"html_url":"https://github.com/mobasherahmed/Portfolio/commit/ddb95cb3564910aaf742e0ea8088d23a806d98a5","sha":"ddb95cb3564910aaf742e0ea8088d23a806d98a5","url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/ddb95cb3564910aaf742e0ea8088d23a806d98a5"}],"sha":"de844aa75cf9771ef577f10a79a72fba481bc465","url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/de844aa75cf9771ef577f10a79a72fba481bc465"},{"author":null,"comments_url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/ddb95cb3564910aaf742e0ea8088d23a806d98a5/comments","commit":{"author":{"date":"2026-09-11T20:23:50Z","email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"comment_count":0,"committer":{"date":"2026-09-11T20:23:50Z","email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"message":"Add Open Graph cover, lead with the platform work\n\n- Generate assets/images/og-cover.png. index.html has referenced it since the\n  SEO pass but it never existed, so every LinkedIn, Slack and WhatsApp share of\n  the portfolio rendered a blank card.\n- The work section ran to eight case studies of equal weight across 3,700px.\n  It now leads with the four Netsync platform studies plus Geidea POS and\n  WinjiGo; Meqati and Health Heroes are 2019-21 Ionic work that read against\n  the positioning, and both remain in the archive. Driven by a `featured` flag\n  in the locale files so it stays a content decision, with a test pinning the\n  set so it cannot silently empty.\n\nCo-Authored-By: Claude Opus 5 (1M context) <noreply@anthropic.com>","tree":{"sha":"9b43ee6b6991b1c02fb95d59b95f63af64c06058","url":"https://api.github.com/repos/mobasherahmed/Portfolio/git/trees/9b43ee6b6991b1c02fb95d59b95f63af64c06058"},"url":"https://api.github.com/repos/mobasherahmed/Portfolio/git/commits/ddb95cb3564910aaf742e0ea8088d23a806d98a5","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/mobasherahmed/Portfolio/commit/ddb95cb3564910aaf742e0ea8088d23a806d98a5","node_id":"C_kwDOIEi60doAKGRkYjk1Y2IzNTY0OTEwYWFmNzQyZTBlYTgwODhkMjNhODA2ZDk4YTU","parents":[{"html_url":"https://github.com/mobasherahmed/Portfolio/commit/974e1016afd7b3070d16be73136f28d0d3171b16","sha":"974e1016afd7b3070d16be73136f28d0d3171b16","url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/974e1016afd7b3070d16be73136f28d0d3171b16"}],"sha":"ddb95cb3564910aaf742e0ea8088d23a806d98a5","url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/ddb95cb3564910aaf742e0ea8088d23a806d98a5"},{"author":null,"comments_url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/974e1016afd7b3070d16be73136f28d0d3171b16/comments","commit":{"author":{"date":"2026-09-11T20:09:08Z","email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"comment_count":0,"committer":{"date":"2026-09-11T20:09:08Z","email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"message":"Retouch portrait and close recruiter-facing gaps\n\nPortrait\n- Reframed from the 2736px original and treated: tone and warmth correction,\n  then an elliptical falloff centred on the face so the floral arch and the\n  table clutter drop to near-black. It reads as a portrait rather than an event\n  photo, and it now sits in the dark palette instead of fighting it. A real\n  headshot is still the better answer; this is the most the source allows.\n\nReviewed the page the way someone screening candidates would, and fixed what\nthat turned up:\n\n- On a phone there was no route to GitHub or LinkedIn at all. The side rails are\n  d-none d-md-block, so the only visible link below 768px was a mailto. Added a\n  links row to the contact section: GitHub, LinkedIn, resume, email.\n- Section numbering read 01, 02, 03, 05 — the 04 component is commented out.\n- Two nested <main> elements, from adding the landmark while home.component.html\n  already had one.\n- The hero answered neither \"what roles\" nor \"where\". Both now sit under the\n  intro instead of 7,000px down in the contact section.\n- Seven of eight case studies had no link and no explanation, which reads as an\n  omission. They are labelled as private enterprise repositories.\n- The project archive existed at /projects but nothing linked to it. The work\n  section now ends with a link, language-prefixed so /ar stays in Arabic.\n  RouterModule was missing from HomeModule, so routerLink rendered no href.\n\nCo-Authored-By: Claude Opus 5 (1M context) <noreply@anthropic.com>","tree":{"sha":"8cfa3bc7f59b05ddb42296c43bfe3c3b00bfbd1e","url":"https://api.github.com/repos/mobasherahmed/Portfolio/git/trees/8cfa3bc7f59b05ddb42296c43bfe3c3b00bfbd1e"},"url":"https://api.github.com/repos/mobasherahmed/Portfolio/git/commits/974e1016afd7b3070d16be73136f28d0d3171b16","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/mobasherahmed/Portfolio/commit/974e1016afd7b3070d16be73136f28d0d3171b16","node_id":"C_kwDOIEi60doAKDk3NGUxMDE2YWZkN2IzMDcwZDE2YmU3MzEzNmYyOGQwZDMxNzFiMTY","parents":[{"html_url":"https://github.com/mobasherahmed/Portfolio/commit/992ec36d141124c88d5f2d825529fdd159da2efb","sha":"992ec36d141124c88d5f2d825529fdd159da2efb","url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/992ec36d141124c88d5f2d825529fdd159da2efb"}],"sha":"974e1016afd7b3070d16be73136f28d0d3171b16","url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/974e1016afd7b3070d16be73136f28d0d3171b16"},{"author":null,"comments_url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/992ec36d141124c88d5f2d825529fdd159da2efb/comments","commit":{"author":{"date":"2026-09-11T19:28:32Z","email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"comment_count":0,"committer":{"date":"2026-09-11T19:28:32Z","email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"message":"Fix RTL layout, make headings fluid, restructure case studies\n\nChecked the Arabic build in a real browser rather than trusting the CSS.\n\nRTL layout\n- The skip link was parked at left:-9999px. Under dir=\"rtl\" that extends the\n  document''s scrollable width by the same amount: documentElement.scrollWidth\n  was 11439px against a 1440px viewport, which pushed the whole page into a\n  narrow column. Hidden by clipping instead. Both locales now measure\n  scrollWidth == clientWidth at 1440px and at 390px.\n- Global [dir=\"rtl\"] rules lost to component styles, which carry the\n  encapsulation attribute. Moved them into the components as :host-context, so\n  the experience rail, list markers, portrait frame and footer rails actually\n  mirror. Bullet arrows flip glyph as well as side.\n- Tell Owl the direction and rebuild it on language change; its stage is laid\n  out with absolute offsets fixed at creation.\n- The experience rail gets real width in RTL: the LTR rules give the anchor\n  width:110% to spill harmlessly right, which mirrored into a clipped\n  \"Capital Link Globe\".\n- Skills columns get a gap; each column''s marker sits at its own inline edge\n  and without one it read as belonging to the next column.\n\nTypography\n- Banner headings were a flat 80px with no breakpoint at all — they overflowed\n  on phones in both locales. Now clamp(), with a lower ceiling and looser\n  leading for Arabic, which sets denser. Removed the stepped !important\n  overrides that replaced them; they still referenced the old h2/h3 hierarchy.\n- Restore the heading styles to match the markup: the SEO pass made the name\n  the h1, but the stylesheet still dressed h1 as the small green eyebrow, so\n  the name rendered at 16px and the role at 80px.\n- Shorten the Arabic hero line and drop its trailing full stop, which bidi\n  places at the far end.\n\nCase studies\n- Text-only studies now split into identity/stack and narrative columns rather\n  than leaving half the row empty, collapsing to one column under 900px.\n\nCo-Authored-By: Claude Opus 5 (1M context) <noreply@anthropic.com>","tree":{"sha":"1bf840ea48dd705ff6b1aefb45f97ef0ece6b590","url":"https://api.github.com/repos/mobasherahmed/Portfolio/git/trees/1bf840ea48dd705ff6b1aefb45f97ef0ece6b590"},"url":"https://api.github.com/repos/mobasherahmed/Portfolio/git/commits/992ec36d141124c88d5f2d825529fdd159da2efb","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/mobasherahmed/Portfolio/commit/992ec36d141124c88d5f2d825529fdd159da2efb","node_id":"C_kwDOIEi60doAKDk5MmVjMzZkMTQxMTI0Yzg4ZDVmMmQ4MjU1MjlmZGQxNTlkYTJlZmI","parents":[{"html_url":"https://github.com/mobasherahmed/Portfolio/commit/cb57dbe7518c23b9bcd99d5317fee94f1f30ff2d","sha":"cb57dbe7518c23b9bcd99d5317fee94f1f30ff2d","url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/cb57dbe7518c23b9bcd99d5317fee94f1f30ff2d"}],"sha":"992ec36d141124c88d5f2d825529fdd159da2efb","url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/992ec36d141124c88d5f2d825529fdd159da2efb"},{"author":null,"comments_url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/cb57dbe7518c23b9bcd99d5317fee94f1f30ff2d/comments","commit":{"author":{"date":"2026-09-11T18:22:17Z","email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"comment_count":0,"committer":{"date":"2026-09-11T18:22:17Z","email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"message":"Fix Arabic rendering, mirror RTL layout, reframe portrait\n\nArabic was unreadable for one root cause: Calibre and SF Mono are declared with\nunicode-range U+000-5FF and Arabic begins at U+0600, so every Arabic glyph fell\nback to whatever the OS chose, with mismatched weights and metrics.\n\n- Self-host IBM Plex Sans Arabic, Arabic subset only, four weights (144KB total),\n  appended to both font stacks behind the Latin faces so Latin is unaffected.\n- Mirror the layout rather than just the text direction: experience tab borders\n  and indicators, list bullet arrows (and their glyph), section-title rule and\n  number, footer side rails, and the Bootstrap 4 directional utilities, which\n  ship LTR-only. Latin technology names are bidi-isolated so \"AG Grid\" keeps its\n  order inside Arabic text. Looser line-height for Arabic.\n- Reframe the portrait from the 2736px original recovered from history: the site\n  was showing a full-body event photo at 300x300, so the face was unreadable at\n  avatar sizes. Now head-and-shoulders at 800px.\n\nCo-Authored-By: Claude Opus 5 (1M context) <noreply@anthropic.com>","tree":{"sha":"86509bbb19c20ca5087d63f5052785919411b6ac","url":"https://api.github.com/repos/mobasherahmed/Portfolio/git/trees/86509bbb19c20ca5087d63f5052785919411b6ac"},"url":"https://api.github.com/repos/mobasherahmed/Portfolio/git/commits/cb57dbe7518c23b9bcd99d5317fee94f1f30ff2d","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/mobasherahmed/Portfolio/commit/cb57dbe7518c23b9bcd99d5317fee94f1f30ff2d","node_id":"C_kwDOIEi60doAKGNiNTdkYmU3NTE4YzIzYjliY2Q5OWQ1MzE3ZmVlOTRmMWYzMGZmMmQ","parents":[{"html_url":"https://github.com/mobasherahmed/Portfolio/commit/d2174a08efadac1046a944e9935f49b8743872ee","sha":"d2174a08efadac1046a944e9935f49b8743872ee","url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/d2174a08efadac1046a944e9935f49b8743872ee"}],"sha":"cb57dbe7518c23b9bcd99d5317fee94f1f30ff2d","url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/cb57dbe7518c23b9bcd99d5317fee94f1f30ff2d"},{"author":null,"comments_url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/d2174a08efadac1046a944e9935f49b8743872ee/comments","commit":{"author":{"date":"2026-09-11T18:08:21Z","email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"comment_count":0,"committer":{"date":"2026-09-11T18:08:21Z","email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"message":"Merge: senior frontend brand overhaul\n\nRebuilds portfolio content from the CV, fixes the 404 on the URL printed there,\nadds EN/AR with RTL, SEO metadata, a passing test suite and CI deployment.\n\nCo-Authored-By: Claude Opus 5 (1M context) <noreply@anthropic.com>","tree":{"sha":"827e172218bf606db222eb82a8f7f9ef421ab1a8","url":"https://api.github.com/repos/mobasherahmed/Portfolio/git/trees/827e172218bf606db222eb82a8f7f9ef421ab1a8"},"url":"https://api.github.com/repos/mobasherahmed/Portfolio/git/commits/d2174a08efadac1046a944e9935f49b8743872ee","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/mobasherahmed/Portfolio/commit/d2174a08efadac1046a944e9935f49b8743872ee","node_id":"C_kwDOIEi60doAKGQyMTc0YTA4ZWZhZGFjMTA0NmE5NDRlOTkzNWY0OWI4NzQzODcyZWU","parents":[{"html_url":"https://github.com/mobasherahmed/Portfolio/commit/5c00bebf947f521d00a55272133ce94aadb36e5c","sha":"5c00bebf947f521d00a55272133ce94aadb36e5c","url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/5c00bebf947f521d00a55272133ce94aadb36e5c"},{"html_url":"https://github.com/mobasherahmed/Portfolio/commit/575a906becdd9a1d66d962168794bb84e3a76795","sha":"575a906becdd9a1d66d962168794bb84e3a76795","url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/575a906becdd9a1d66d962168794bb84e3a76795"}],"sha":"d2174a08efadac1046a944e9935f49b8743872ee","url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/d2174a08efadac1046a944e9935f49b8743872ee"},{"author":null,"comments_url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/575a906becdd9a1d66d962168794bb84e3a76795/comments","commit":{"author":{"date":"2026-09-11T18:07:54Z","email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"comment_count":0,"committer":{"date":"2026-09-11T18:07:54Z","email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"message":"Drop footer attribution, add 2026 CV, deploy via gh-pages\n\n- Remove the \"based on\" line from the footer, its style block and both locale\n  files. Credit for the upstream MIT design stays in the README, which is where\n  the licence notice needs to live.\n- Replace the placeholder resume with the 2026 CV, renamed to the stable\n  filename cv.constants.ts resolves.\n- Pages serves the gh-pages branch and changing that setting needs admin, so the\n  workflow publishes the build output to that branch instead of using\n  actions/deploy-pages. Route verification now also asserts the CV ships.\n- README: current stack, test commands, and why routes are pre-rendered.\n\nCo-Authored-By: Claude Opus 5 (1M context) <noreply@anthropic.com>","tree":{"sha":"827e172218bf606db222eb82a8f7f9ef421ab1a8","url":"https://api.github.com/repos/mobasherahmed/Portfolio/git/trees/827e172218bf606db222eb82a8f7f9ef421ab1a8"},"url":"https://api.github.com/repos/mobasherahmed/Portfolio/git/commits/575a906becdd9a1d66d962168794bb84e3a76795","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/mobasherahmed/Portfolio/commit/575a906becdd9a1d66d962168794bb84e3a76795","node_id":"C_kwDOIEi60doAKDU3NWE5MDZiZWNkZDlhMWQ2NmQ5NjIxNjg3OTRiYjg0ZTNhNzY3OTU","parents":[{"html_url":"https://github.com/mobasherahmed/Portfolio/commit/4fd2df2009bbb563be30d3410c280bb75c78fd89","sha":"4fd2df2009bbb563be30d3410c280bb75c78fd89","url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/4fd2df2009bbb563be30d3410c280bb75c78fd89"}],"sha":"575a906becdd9a1d66d962168794bb84e3a76795","url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/575a906becdd9a1d66d962168794bb84e3a76795"},{"author":null,"comments_url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/4fd2df2009bbb563be30d3410c280bb75c78fd89/comments","commit":{"author":{"date":"2026-09-11T17:59:34Z","email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"comment_count":0,"committer":{"date":"2026-09-11T17:59:47Z","email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"message":"Ignore local .brand/ working notes\n\nDrafts for the GitHub profile README, LinkedIn copy and the account-level steps\nlive in .brand/ so they stay out of the build and off the deployed site.\n\nCo-Authored-By: Claude Opus 5 (1M context) <noreply@anthropic.com>","tree":{"sha":"e7507573b66c2057d96d09eb5be2abf0743a956f","url":"https://api.github.com/repos/mobasherahmed/Portfolio/git/trees/e7507573b66c2057d96d09eb5be2abf0743a956f"},"url":"https://api.github.com/repos/mobasherahmed/Portfolio/git/commits/4fd2df2009bbb563be30d3410c280bb75c78fd89","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/mobasherahmed/Portfolio/commit/4fd2df2009bbb563be30d3410c280bb75c78fd89","node_id":"C_kwDOIEi60doAKDRmZDJkZjIwMDliYmI1NjNiZTMwZDM0MTBjMjgwYmI3NWM3OGZkODk","parents":[{"html_url":"https://github.com/mobasherahmed/Portfolio/commit/bc982b350e1d692037febe5a8ca5590d7c5d0861","sha":"bc982b350e1d692037febe5a8ca5590d7c5d0861","url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/bc982b350e1d692037febe5a8ca5590d7c5d0861"}],"sha":"4fd2df2009bbb563be30d3410c280bb75c78fd89","url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/4fd2df2009bbb563be30d3410c280bb75c78fd89"},{"author":null,"comments_url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/bc982b350e1d692037febe5a8ca5590d7c5d0861/comments","commit":{"author":{"date":"2026-09-11T14:19:16Z","email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"comment_count":0,"committer":{"date":"2026-09-11T14:19:16Z","email":"ahmedmobasher@Ahmeds-MacBook-Pro.local","name":"Ahmed Mobasher"},"message":"Rebuild portfolio content and fix deployment defects\n\nThe deployed site contradicted the CV and carried defects from the template\nit was forked from. Content is now sourced from the CV alone.\n\nDeployment\n- /en returned HTTP 404: the language prefix was pushed client-side after\n  bootstrap, so GitHub Pages served its 404 document. tools/prerender-routes.js\n  now emits a real index.html per route, each with its own lang/dir/canonical.\n- Add GitHub Actions workflow: test, build, verify routes, deploy to Pages.\n\nContent\n- Replace 7 job entries (4 simultaneously \"Present\", 2 employers absent from\n  the CV) with the 6 CV roles, Netsync included.\n- Rewrite projects as case studies with context and engineering challenge;\n  case studies render text-first when a project has no public screenshots.\n- \"+4 years\" -> \"9+ years\". Archive page listed the original author''s\n  repositories; it now lists this CV''s projects.\n- Replace leftover Spanish locale with Arabic, with RTL handling in\n  LanguageService and styles. en/ar key parity asserted in tests.\n\nDefects\n- Contact CTA opened mailto: to an unrelated address.\n- downloadCV() built \"assets/cv\" + filename with no separator.\n- production.sh copied from a dist path the build never produced.\n- Project identity carried three different owners across package.json,\n  angular.json, firebase.json and .firebaserc.\n\nSEO and accessibility\n- Open Graph, Twitter cards, JSON-LD Person, canonical, hreflang, robots.txt,\n  sitemap.xml. h1 now carries the name rather than \"Hello! My name is\".\n- Skip link, focus-visible styles, real alt text, aria-labels, keyboard-\n  operable menu button, prefers-reduced-motion.\n\nAssets\n- Drop the previous author''s project images; 27MB -> 8.7MB. HealthHeroes .webp\n  files were ~1.9MB each against ~170KB PNGs of the same shots.\n- Language switcher no longer hot-links flag GIFs from a third-party host.\n\nTests\n- Suite could not start: karma pointed at a styles.css that does not exist.\n  Shared setup loads real translations so *ngFor over translated arrays works.\n- Add content assertions: locale key parity, employer list matches the CV,\n  exactly one current role, no stale claims. 23 passing.\n\nCo-Authored-By: Claude Opus 5 (1M context) <noreply@anthropic.com>","tree":{"sha":"2d18e9303f4be97b4fc3a083011485e95fd962e1","url":"https://api.github.com/repos/mobasherahmed/Portfolio/git/trees/2d18e9303f4be97b4fc3a083011485e95fd962e1"},"url":"https://api.github.com/repos/mobasherahmed/Portfolio/git/commits/bc982b350e1d692037febe5a8ca5590d7c5d0861","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/mobasherahmed/Portfolio/commit/bc982b350e1d692037febe5a8ca5590d7c5d0861","node_id":"C_kwDOIEi60doAKGJjOTgyYjM1MGUxZDY5MjAzN2ZlYmU1YThjYTU1OTBkN2M1ZDA4NjE","parents":[{"html_url":"https://github.com/mobasherahmed/Portfolio/commit/5c00bebf947f521d00a55272133ce94aadb36e5c","sha":"5c00bebf947f521d00a55272133ce94aadb36e5c","url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/5c00bebf947f521d00a55272133ce94aadb36e5c"}],"sha":"bc982b350e1d692037febe5a8ca5590d7c5d0861","url":"https://api.github.com/repos/mobasherahmed/Portfolio/commits/bc982b350e1d692037febe5a8ca5590d7c5d0861"}],"requestUrl":"https://api.github.com/repos/mobasherahmed/Portfolio/commits?per_page=100&page=1&sha=de844aa75cf9771ef577f10a79a72fba481bc465&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T15%3A52%3A39.958Z"}');
